options.getOption:
// Access data from context (Grafana 12)
const seriesData = context?.panel?.data?.series;

if (!seriesData || seriesData.length === 0) {
  return {
    title: { text: 'No data available', left: 'center' },
    graphic: { type: 'text', left: 'center', top: 'middle',
      style: { text: 'No data in selected time range', fontSize: 16, fill: '#999' } }
  };
}

const series = seriesData[0];
const fields = series.fields;
const variantField = fields.find(function(f) { return f.name === 'variant'; });
const actionSetField = fields.find(function(f) { return f.name === 'action_set_id'; });
const avgKpiField = fields.find(function(f) { return f.name === 'avg_kpi'; });
const uiField = fields.find(function(f) { return f.name === 'ui_name'; });

if (!variantField || !actionSetField || !avgKpiField) {
  return {
    title: { text: 'No data available', left: 'center' },
    graphic: { type: 'text', left: 'center', top: 'middle',
      style: { text: 'No KPI measurements in selected time range', fontSize: 14, fill: '#999' } }
  };
}

const variants = Array.from(variantField.values.buffer || variantField.values);
const actionSets = Array.from(actionSetField.values.buffer || actionSetField.values);
const kpis = Array.from(avgKpiField.values.buffer || avgKpiField.values).map(function(v) { return Math.round(v); });
const uiNames = uiField ? Array.from(uiField.values.buffer || uiField.values) : [];

if (actionSets.length === 0) {
  return {
    title: { text: 'No measurements found', left: 'center' },
    graphic: { type: 'text', left: 'center', top: 'middle',
      style: { text: 'Try expanding the time range', fontSize: 14, fill: '#999' } }
  };
}

const uniqueCategories = [];
const uniqueVariants = [];
for (let i = 0; i < actionSets.length; i++) {
  if (uniqueCategories.indexOf(actionSets[i]) === -1) uniqueCategories.push(actionSets[i]);
  if (uniqueVariants.indexOf(variants[i]) === -1) uniqueVariants.push(variants[i]);
}

const pivot = {};
for (let i = 0; i < actionSets.length; i++) {
  if (!pivot[variants[i]]) pivot[variants[i]] = {};
  pivot[variants[i]][actionSets[i]] = kpis[i];
}

// Per-axis scale: each indicator gets its OWN max so a huge value (e.g. reboot)
// no longer crushes the small axes. Absolute ms still shown in the tooltip.
const catMax = {};
uniqueCategories.forEach(function(cat) {
  let m = 0;
  uniqueVariants.forEach(function(v) {
    const val = pivot[v] ? pivot[v][cat] : null;
    if (val != null && !isNaN(val) && val > m) m = val;
  });
  catMax[cat] = Math.max(1, Math.ceil(m * 1.2));
});

// Track which axis the cursor is nearest so the tooltip shows ONE kpi broken
// down per device (the repartition), not one device across all axes.
// Bound lazily (the chart instance may not exist at getOption time) and resolved
// via convertFromPixel (public API), falling back to radar geometry.
function _bindRadarAxis(ctx) {
  try {
    const chart = ctx && ctx.panel && ctx.panel.chart;
    if (!chart || !chart.getZr) return false;
    if (chart.__radarAxisBound) return true;
    chart.__radarAxisBound = true;
    chart.getZr().on('mousemove', function(e) {
      try {
        const mx = (e.offsetX != null ? e.offsetX : e.zrX);
        const my = (e.offsetY != null ? e.offsetY : e.zrY);
        // 1) public convertFromPixel: radar returns [indicatorIndex, value]
        try {
          const r = chart.convertFromPixel({ radarIndex: 0 }, [mx, my]);
          if (r && r.length && r[0] != null && !isNaN(r[0])) {
            chart.__radarAxisIdx = Math.round(r[0]);
            return;
          }
        } catch (e1) {}
        // 2) geometry fallback: nearest indicator by angle around the center
        const comp = chart.getModel().getComponent('radar');
        const rc = comp && comp.coordinateSystem;
        const axes = (rc && rc.getIndicatorAxes) ? rc.getIndicatorAxes() : [];
        const n = axes.length;
        if (!rc || !n) { chart.__radarAxisIdx = -1; return; }
        let cx = rc.cx, cy = rc.cy;
        if ((cx == null || cy == null) && rc.dataToPoint) {
          const c = rc.dataToPoint(axes[0].scale.getExtent()[0], 0);
          if (c) { cx = c[0]; cy = c[1]; }
        }
        const mang = Math.atan2(cy - my, mx - cx);
        let best = -1, bestD = Infinity;
        for (let i = 0; i < n; i++) {
          let a = axes[i].angle;
          if (a == null && rc.dataToPoint) {
            const ext = axes[i].scale.getExtent();
            const tip = rc.dataToPoint(ext[1] || 1, i);
            if (tip) a = Math.atan2(cy - tip[1], tip[0] - cx);
          }
          if (a == null) continue;
          let d = Math.abs(mang - a);
          d = Math.min(d, Math.PI * 2 - d);
          if (d < bestD) { bestD = d; best = i; }
        }
        chart.__radarAxisIdx = best;
      } catch (err) { chart.__radarAxisIdx = -1; }
    });
    return true;
  } catch (e) { return false; }
}
if (!_bindRadarAxis(context) && typeof setTimeout === 'function') {
  setTimeout(function() { _bindRadarAxis(context); }, 0);
  setTimeout(function() { _bindRadarAxis(context); }, 300);
}

const palette = ['#5470c6', '#91cc75', '#fac858', '#ee6666', '#73c0de', '#3ba272', '#fc8452', '#9a60b4'];
const radarData = uniqueVariants.map(function(variant, idx) {
  const color = palette[idx % palette.length];
  const values = uniqueCategories.map(function(cat) {
    return (pivot[variant] && pivot[variant][cat] != null) ? pivot[variant][cat] : 0;
  });
  return {
    value: values, name: variant, symbol: 'circle', symbolSize: 5,
    areaStyle: { opacity: 0.2, color: color },
    lineStyle: { width: 2, color: color },
    itemStyle: { color: color, borderColor: '#fff', borderWidth: 1 },
    label: { show: false }
  };
});

const uiLabel = uiNames.length ? uiNames[0] : '';

return {
  title: { text: 'Radar' + (uiLabel ? ' - ' + uiLabel : ''), left: 'center', textStyle: { fontSize: 16 } },
  tooltip: {
    trigger: 'item',
    formatter: function(params) {
      const chart = (typeof context !== 'undefined' && context && context.panel) ? context.panel.chart : null;
      const ci = (chart && chart.__radarAxisIdx != null) ? chart.__radarAxisIdx : -1;
      if (ci >= 0 && ci < uniqueCategories.length) {
        const cat = uniqueCategories[ci];
        const rows = uniqueVariants.map(function(v) {
          const val = (pivot[v] && pivot[v][cat] != null) ? pivot[v][cat] : null;
          const txt = v + ': ' + (val == null ? '—' : val + ' ms');
          return (v === params.name) ? ('<b>' + txt + '</b>') : txt;
        });
        return '<b>' + cat + '</b><br/>' + rows.join('<br/>');
      }
      if (Array.isArray(params.value)) {
        return '<b>' + (params.name || params.seriesName) + '</b><br/>' + uniqueCategories.map(function(cat, i) {
          return cat + ': ' + params.value[i] + ' ms';
        }).join('<br/>');
      }
      return (params.name || '') + ': ' + Math.round(params.value) + ' ms';
    }
  },
  legend: { data: uniqueVariants, bottom: 5, textStyle: { color: '#ccc' } },
  radar: {
    indicator: uniqueCategories.map(function(cat) { return { name: cat, max: catMax[cat] }; }),
    radius: '60%', splitNumber: 4,
    name: { textStyle: { color: '#fff', fontSize: 11 } },
    splitLine: { lineStyle: { color: ['rgba(255, 255, 255, 0.1)', 'rgba(255, 255, 255, 0.2)'].reverse() } },
    splitArea: { show: true, areaStyle: { color: ['rgba(255, 255, 255, 0.02)', 'rgba(255, 255, 255, 0.05)'] } },
    axisLine: { lineStyle: { color: 'rgba(255, 255, 255, 0.2)' } }
  },
  series: [{ name: 'KPI Measurements', type: 'radar', data: radarData }]
};

